  1→"use client";
  2→
  3→import { useState } from "react";
  4→import { Play, Trash2, ExternalLink, Check, ChevronRight } from "lucide-react";
  5→import { Button } from "@/components/ui/button";
  6→import { cn } from "@/lib/utils";
  7→import type { Task, TaskStatus, TaskPriority } from "@/lib/types";
  8→
  9→const PRIORITY_COLORS: Record<TaskPriority, string> = {
 10→  urgent: "bg-red-500/20 text-red-400 border-red-500/30",
 11→  high: "bg-orange-500/20 text-orange-400 border-orange-500/30",
 12→  medium: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
 13→  low: "bg-muted text-muted-foreground border-border",
 14→};
 15→
 16→const STATUS_COLORS: Record<TaskStatus, string> = {
 17→  todo: "border-border text-muted-foreground",
 18→  "in-progress": "bg-blue-500/20 text-blue-400 border-blue-500/30",
 19→  done: "bg-green-500/20 text-green-400 border-green-500/30",
 20→};
 21→
 22→const STATUS_LABELS: Record<TaskStatus, string> = {
 23→  todo: "todo",
 24→  "in-progress": "in progress",
 25→  done: "done",
 26→};
 27→
 28→const NEXT_STATUS: Record<TaskStatus, TaskStatus> = {
 29→  todo: "in-progress",
 30→  "in-progress": "done",
 31→  done: "todo",
 32→};
 33→
 34→const PRIORITIES: TaskPriority[] = ["urgent", "high", "medium", "low"];
 35→
 36→function timeAgo(ts: number): string {
 37→  const seconds = Math.floor((Date.now() - ts) / 1000);
 38→  if (seconds < 60) return "just now";
 39→  const minutes = Math.floor(seconds / 60);
 40→  if (minutes < 60) return `${minutes}m ago`;
 41→  const hours = Math.floor(minutes / 60);
 42→  if (hours < 24) return `${hours}h ago`;
 43→  const days = Math.floor(hours / 24);
 44→  if (days < 30) return `${days}d ago`;
 45→  const months = Math.floor(days / 30);
 46→  return `${months}mo ago`;
 47→}
 48→
 49→interface TaskCardProps {
 50→  task: Task;
 51→  onUpdate: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
 52→  onDelete: (taskId: string) => void;
 53→  onDelegate: (taskId: string) => void;
 54→  onSelectAgent: (agentId: string) => void;
 55→}
 56→
 57→export function TaskCard({ task, onUpdate, onDelete, onDelegate, onSelectAgent }: TaskCardProps) {
 58→  const [expanded, setExpanded] = useState(false);
 59→  const [editing, setEditing] = useState(false);
 60→  const [editTitle, setEditTitle] = useState(task.title);
 61→  const [editDesc, setEditDesc] = useState(task.description);
 62→
 63→  const handleSaveEdit = () => {
 64→    if (!editTitle.trim()) return;
 65→    onUpdate(task.id, { title: editTitle.trim(), description: editDesc.trim() });
 66→    setEditing(false);
 67→  };
 68→
 69→  const handleCancelEdit = () => {
 70→    setEditTitle(task.title);
 71→    setEditDesc(task.description);
 72→    setEditing(false);
 73→  };
 74→
 75→  const handleCardClick = (e: React.MouseEvent) => {
 76→    if (editing) return;
 77→    const target = e.target as HTMLElement;
 78→    if (target.closest("button") || target.closest("input") || target.closest("textarea")) return;
 79→    setExpanded((v) => !v);
 80→  };
 81→
 82→  return (
 83→    <div
 84→      className={cn("group rounded-md border bg-card p-3 text-xs cursor-pointer transition-colors", expanded && "border-primary/30")}
 85→      onClick={handleCardClick}
 86→    >
 87→      <div className="flex items-start justify-between gap-2">
 88→        <div className="flex items-center gap-1.5 min-w-0">
 89→          <ChevronRight
 90→            className={cn("size-3 shrink-0 text-muted-foreground transition-transform", expanded && "rotate-90")}
 91→          />
 92→          <span
 93→            className={cn("shrink-0 rounded px-1.5 py-0.5 text-[10px] font-medium border", PRIORITY_COLORS[task.priority])}
 94→          >
 95→            {task.priority}
 96→          </span>
 97→          {editing ? (
 98→            <input
 99→              className="min-w-0 flex-1 bg-transparent font-medium outline-none border-b border-primary"
100→              value={editTitle}
101→              onChange={(e) => setEditTitle(e.target.value)}
102→              onKeyDown={(e) => {
103→                if (e.key === "Enter") handleSaveEdit();
104→                if (e.key === "Escape") handleCancelEdit();
105→              }}
106→              autoFocus
107→            />
108→          ) : (
109→            <span
110→              className={cn(
111→                "truncate font-medium",
112→                task.status === "done" && "line-through text-muted-foreground"
113→              )}
114→              onDoubleClick={() => setEditing(true)}
115→            >
116→              {task.title}
117→            </span>
118→          )}
119→        </div>
120→        <div className="flex shrink-0 items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
121→          {!task.agentId && task.status !== "done" && (
122→            <Button
123→              variant="ghost"
124→              size="icon-xs"
125→              onClick={() => onDelegate(task.id)}
126→              title="Delegate to agent"
127→            >
128→              <Play className="size-3" />
129→            </Button>
130→          )}
131→          <Button
132→            variant="ghost"
133→            size="icon-xs"
134→            onClick={() => onDelete(task.id)}
135→            title="Delete task"
136→          >
137→            <Trash2 className="size-3" />
138→          </Button>
139→        </div>
140→      </div>
141→
142→      {editing ? (
143→        <div className="mt-2 space-y-2">
144→          <textarea
145→            className="w-full rounded border bg-transparent p-1.5 text-xs outline-none resize-none"
146→            value={editDesc}
147→            onChange={(e) => setEditDesc(e.target.value)}
148→            rows={2}
149→            placeholder="Description..."
150→          />
151→          <div className="flex gap-1">
152→            <Button size="xs" onClick={handleSaveEdit}>
153→              <Check className="size-3 mr-1" />
154→              Save
155→            </Button>
156→            <Button size="xs" variant="ghost" onClick={handleCancelEdit}>
157→              Cancel
158→            </Button>
159→          </div>
160→        </div>
161→      ) : expanded ? (
162→        <div className="mt-2 space-y-2">
163→          {task.description && (
164→            <p className="text-muted-foreground whitespace-pre-wrap">{task.description}</p>
165→          )}
166→
167→          {/* Priority selector */}
168→          <div className="flex items-center gap-1">
169→            <span className="text-muted-foreground mr-1">priority</span>
170→            {PRIORITIES.map((p) => (
171→              <button
172→                key={p}
173→                className={cn(
174→                  "rounded px-1.5 py-0.5 text-[10px] font-medium border transition-colors",
175→                  task.priority === p ? PRIORITY_COLORS[p] : "border-transparent text-muted-foreground/50 hover:text-muted-foreground"
176→                )}
177→                onClick={() => onUpdate(task.id, { priority: p })}
178→              >
179→                {p}
180→              </button>
181→            ))}
182→          </div>
183→
184→          {/* Metadata */}
185→          <div className="flex flex-col gap-0.5 text-[10px] text-muted-foreground/70">
186→            <span>created {timeAgo(task.createdAt)}</span>
187→            {task.updatedAt !== task.createdAt && (
188→              <span>updated {timeAgo(task.updatedAt)}</span>
189→            )}
190→            <span className="font-mono">id: {task.id}</span>
191→          </div>
192→        </div>
193→      ) : (
194→        task.description && (
195→          <p className="mt-1 text-muted-foreground line-clamp-2">{task.description}</p>
196→        )
197→      )}
198→
199→      <div className="mt-2 flex items-center justify-between">
200→        <button
201→          className={cn(
202→            "rounded-full border px-2 py-0.5 text-[10px] font-medium transition-colors hover:brightness-125",
203→            STATUS_COLORS[task.status]
204→          )}
205→          onClick={() => onUpdate(task.id, { status: NEXT_STATUS[task.status] })}
206→          title={`Click to change to "${STATUS_LABELS[NEXT_STATUS[task.status]]}"`}
207→        >
208→          {STATUS_LABELS[task.status]}
209→        </button>
210→
211→        {task.agentId && (
212→          <button
213→            className="flex items-center gap-1 text-[10px] text-primary hover:underline"
214→            onClick={() => onSelectAgent(task.agentId!)}
215→          >
216→            <ExternalLink className="size-2.5" />
217→            view agent
218→          </button>
219→        )}
220→      </div>
221→    </div>
222→  );
223→}
