 1→/**
 2→ * File-based task persistence for the thos dashboard.
 3→ *
 4→ * Stores all tasks in a single JSON file at `.thos/tasks/tasks.json`.
 5→ * Uses the same debounced/sync write pattern as SessionStore.
 6→ */
 7→
 8→import { mkdirSync, writeFileSync, readFileSync, existsSync } from "fs";
 9→import { join } from "path";
10→import type { Task } from "../lib/types";
11→
12→const TASK_DIR = join(process.cwd(), ".thos", "tasks");
13→const TASK_FILE = join(TASK_DIR, "tasks.json");
14→
15→export class TaskStore {
16→  private debounceTimer: ReturnType<typeof setTimeout> | null = null;
17→
18→  constructor() {
19→    mkdirSync(TASK_DIR, { recursive: true });
20→  }
21→
22→  /** Load all tasks from disk. Returns empty array if file missing. */
23→  loadAll(): Task[] {
24→    if (!existsSync(TASK_FILE)) return [];
25→    try {
26→      const raw = readFileSync(TASK_FILE, "utf-8");
27→      return JSON.parse(raw) as Task[];
28→    } catch (err) {
29→      console.error("[task-store] failed to load:", err);
30→      return [];
31→    }
32→  }
33→
34→  /** Debounced write (150ms). */
35→  save(tasks: Task[]): void {
36→    if (this.debounceTimer) clearTimeout(this.debounceTimer);
37→    this.debounceTimer = setTimeout(() => {
38→      this.debounceTimer = null;
39→      this.writeFile(tasks);
40→    }, 150);
41→  }
42→
43→  /** Immediate write for critical changes. */
44→  saveSync(tasks: Task[]): void {
45→    if (this.debounceTimer) {
46→      clearTimeout(this.debounceTimer);
47→      this.debounceTimer = null;
48→    }
49→    this.writeFile(tasks);
50→  }
51→
52→  /** Flush pending writes (for graceful shutdown). */
53→  flush(tasks: Task[]): void {
54→    if (this.debounceTimer) {
55→      clearTimeout(this.debounceTimer);
56→      this.debounceTimer = null;
57→    }
58→    this.writeFile(tasks);
59→  }
60→
61→  private writeFile(tasks: Task[]): void {
62→    try {
63→      writeFileSync(TASK_FILE, JSON.stringify(tasks, null, 2));
64→    } catch (err) {
65→      console.error("[task-store] failed to write:", err);
66→    }
67→  }
68→}
