  1→"use client";
  2→
  3→/**
  4→ * Dashboard route (`/dashboard`).
  5→ *
  6→ * Orchestrates the multi-agent WebSocket hook, sidebar, chat panel, and
  7→ * task panel. Clicking "+" or selecting "New Agent" sets `activeAgentId`
  8→ * to `null`, which shows the spawn input. On spawn, the server responds
  9→ * with `spawned` and the hook auto-selects the new agent.
 10→ *
 11→ * ## Loading states
 12→ *
 13→ * Two loading flags from the hook control the UI:
 14→ * - `initialLoadDone` — false until the first `agent_list` arrives from
 15→ *   the server. While false, the sidebar shows skeleton rows.
 16→ * - `historyLoading` — true when the active agent's message history has
 17→ *   not been fetched yet (lazy loading). The chat shows a "Loading
 18→ *   messages..." indicator until the server responds.
 19→ *
 20→ * Sidebar uses `!initialLoadDone`, chat uses `!initialLoadDone || historyLoading`.
 21→ */
 22→
 23→import { useEffect, useState } from "react";
 24→import { useWebSocket } from "@/hooks/use-websocket";
 25→import { AgentSidebar } from "@/components/dashboard/agent-sidebar";
 26→import { Chat } from "@/components/dashboard/chat";
 27→import { TaskPanel } from "@/components/dashboard/task-panel";
 28→import { cn } from "@/lib/utils";
 29→
 30→export default function DashboardPage() {
 31→  const {
 32→    connected,
 33→    initialLoadDone,
 34→    historyLoading,
 35→    agents,
 36→    agentOrder,
 37→    activeAgentId,
 38→    setActiveAgentId,
 39→    activeStatus,
 40→    activeMessages,
 41→    activeRawMessages,
 42→    spawnAgent,
 43→    sendMessage,
 44→    respondToControl,
 45→    respondToUserQuestion,
 46→    killAgent,
 47→    deleteAgent,
 48→    renameAgent,
 49→    clearHistory,
 50→    tasks,
 51→    createTask,
 52→    updateTask,
 53→    deleteTask,
 54→    delegateTask,
 55→  } = useWebSocket();
 56→
 57→  const [showTasks, setShowTasks] = useState(false);
 58→  const [sidebarOpen, setSidebarOpen] = useState(false);
 59→
 60→  useEffect(() => {
 61→    document.title = "thos — dashboard";
 62→  }, []);
 63→
 64→  return (
 65→    <div className="relative flex h-dvh overflow-hidden">
 66→      {/* Sidebar backdrop (mobile only) */}
 67→      {sidebarOpen && (
 68→        <div
 69→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
 70→          onClick={() => setSidebarOpen(false)}
 71→        />
 72→      )}
 73→
 74→      {/* Sidebar drawer */}
 75→      <div
 76→        className={cn(
 77→          "fixed inset-y-0 left-0 z-50 w-56 transition-transform duration-200 ease-in-out md:relative md:z-auto md:translate-x-0 md:transition-none",
 78→          sidebarOpen ? "translate-x-0" : "-translate-x-full"
 79→        )}
 80→      >
 81→        <AgentSidebar
 82→          agents={agents}
 83→          agentOrder={agentOrder}
 84→          activeAgentId={activeAgentId}
 85→          loading={!initialLoadDone}
 86→          onSelect={(id) => {
 87→            setActiveAgentId(id);
 88→            setSidebarOpen(false);
 89→          }}
 90→          onNewAgent={() => {
 91→            setActiveAgentId(null);
 92→            setSidebarOpen(false);
 93→          }}
 94→          onKill={killAgent}
 95→          onDelete={deleteAgent}
 96→          onRename={renameAgent}
 97→          onClearHistory={clearHistory}
 98→        />
 99→      </div>
100→
101→      {/* Main chat area */}
102→      <div className="flex min-w-0 flex-1 flex-col">
103→        <Chat
104→          connected={connected}
105→          loading={!initialLoadDone || historyLoading}
106→          status={activeStatus}
107→          messages={activeMessages}
